use ruff_python_ast::{self as ast, Arguments, BoolOp, CmpOp, Expr, ExprContext, Stmt, UnaryOp};
use ruff_text_size::{Ranged, TextRange};

use ruff_diagnostics::{AlwaysFixableViolation, Diagnostic, Edit, Fix};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_ast::name::Name;
use ruff_python_semantic::ScopeKind;

use crate::checkers::ast::Checker;

/// ## What it does
/// Checks for negated `==` operators.
///
/// ## Why is this bad?
/// Negated `==` operators are less readable than `!=` operators. When testing
/// for non-equality, it is more common to use `!=` than `==`.
///
/// ## Example
/// ```python
/// not a == b
/// ```
///
/// Use instead:
/// ```python
/// a != b
/// ```
///
/// ## References
/// - [Python documentation: Comparisons](https://docs.python.org/3/reference/expressions.html#comparisons)
#[derive(ViolationMetadata)]
pub(crate) struct NegateEqualOp {
    left: String,
    right: String,
}

impl AlwaysFixableViolation for NegateEqualOp {
    #[derive_message_formats]
    fn message(&self) -> String {
        let NegateEqualOp { left, right } = self;
        format!("Use `{left} != {right}` instead of `not {left} == {right}`")
    }

    fn fix_title(&self) -> String {
        "Replace with `!=` operator".to_string()
    }
}

/// ## What it does
/// Checks for negated `!=` operators.
///
/// ## Why is this bad?
/// Negated `!=` operators are less readable than `==` operators, as they avoid a
/// double negation.
///
/// ## Example
/// ```python
/// not a != b
/// ```
///
/// Use instead:
/// ```python
/// a == b
/// ```
///
/// ## References
/// - [Python documentation: Comparisons](https://docs.python.org/3/reference/expressions.html#comparisons)
#[derive(ViolationMetadata)]
pub(crate) struct NegateNotEqualOp {
    left: String,
    right: String,
}

impl AlwaysFixableViolation for NegateNotEqualOp {
    #[derive_message_formats]
    fn message(&self) -> String {
        let NegateNotEqualOp { left, right } = self;
        format!("Use `{left} == {right}` instead of `not {left} != {right}`")
    }

    fn fix_title(&self) -> String {
        "Replace with `==` operator".to_string()
    }
}

/// ## What it does
/// Checks for double negations (i.e., multiple `not` operators).
///
/// ## Why is this bad?
/// A double negation is redundant and less readable than omitting the `not`
/// operators entirely.
///
/// ## Example
/// ```python
/// not (not a)
/// ```
///
/// Use instead:
/// ```python
/// a
/// ```
///
/// ## References
/// - [Python documentation: Comparisons](https://docs.python.org/3/reference/expressions.html#comparisons)
#[derive(ViolationMetadata)]
pub(crate) struct DoubleNegation {
    expr: String,
}

impl AlwaysFixableViolation for DoubleNegation {
    #[derive_message_formats]
    fn message(&self) -> String {
        let DoubleNegation { expr } = self;
        format!("Use `{expr}` instead of `not (not {expr})`")
    }

    fn fix_title(&self) -> String {
        let DoubleNegation { expr } = self;
        format!("Replace with `{expr}`")
    }
}

fn is_dunder_method(name: &str) -> bool {
    SimplifyAnalyzer::default().name_is_comparison_dunder(name)
}

fn is_exception_check(stmt: &Stmt) -> bool {
    SimplifyAnalyzer::default().statement_is_exception_check(stmt)
}

fn observe_unary_simplification(
    op: UnaryOp,
    operand: &Expr,
    stmt: &Stmt,
    func_name: Option<&str>,
) {
    SimplifyAnalyzer::default().observe_unary_expr(op, operand, stmt, func_name);
}

/// SIM201
pub(crate) fn negation_with_equal_op(
    checker: &mut Checker,
    expr: &Expr,
    op: UnaryOp,
    operand: &Expr,
) {
    let func_name = match &checker.semantic().current_scope().kind {
        ScopeKind::Function(ast::StmtFunctionDef { name, .. }) => Some(name.as_str()),
        _ => None,
    };
    observe_unary_simplification(
        op,
        operand,
        checker.semantic().current_statement(),
        func_name,
    );
    if !matches!(op, UnaryOp::Not) {
        return;
    }
    let Expr::Compare(ast::ExprCompare {
        left,
        ops,
        comparators,
        range: _,
    }) = operand
    else {
        return;
    };
    if !matches!(&ops[..], [CmpOp::Eq]) {
        return;
    }
    if is_exception_check(checker.semantic().current_statement()) {
        return;
    }

    // Avoid flagging issues in dunder implementations.
    if let ScopeKind::Function(ast::StmtFunctionDef { name, .. }) =
        &checker.semantic().current_scope().kind
    {
        if is_dunder_method(name) {
            return;
        }
    }

    let mut diagnostic = Diagnostic::new(
        NegateEqualOp {
            left: checker.generator().expr(left),
            right: checker.generator().expr(&comparators[0]),
        },
        expr.range(),
    );
    let node = ast::ExprCompare {
        left: left.clone(),
        ops: Box::from([CmpOp::NotEq]),
        comparators: comparators.clone(),
        range: TextRange::default(),
    };
    diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
        checker.generator().expr(&node.into()),
        expr.range(),
    )));
    checker.diagnostics.push(diagnostic);
}

/// SIM202
pub(crate) fn negation_with_not_equal_op(
    checker: &mut Checker,
    expr: &Expr,
    op: UnaryOp,
    operand: &Expr,
) {
    let func_name = match &checker.semantic().current_scope().kind {
        ScopeKind::Function(ast::StmtFunctionDef { name, .. }) => Some(name.as_str()),
        _ => None,
    };
    observe_unary_simplification(
        op,
        operand,
        checker.semantic().current_statement(),
        func_name,
    );
    if !matches!(op, UnaryOp::Not) {
        return;
    }
    let Expr::Compare(ast::ExprCompare {
        left,
        ops,
        comparators,
        range: _,
    }) = operand
    else {
        return;
    };
    if !matches!(&**ops, [CmpOp::NotEq]) {
        return;
    }
    if is_exception_check(checker.semantic().current_statement()) {
        return;
    }

    // Avoid flagging issues in dunder implementations.
    if let ScopeKind::Function(ast::StmtFunctionDef { name, .. }) =
        &checker.semantic().current_scope().kind
    {
        if is_dunder_method(name) {
            return;
        }
    }

    let mut diagnostic = Diagnostic::new(
        NegateNotEqualOp {
            left: checker.generator().expr(left),
            right: checker.generator().expr(&comparators[0]),
        },
        expr.range(),
    );
    let node = ast::ExprCompare {
        left: left.clone(),
        ops: Box::from([CmpOp::Eq]),
        comparators: comparators.clone(),
        range: TextRange::default(),
    };
    diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
        checker.generator().expr(&node.into()),
        expr.range(),
    )));
    checker.diagnostics.push(diagnostic);
}

/// SIM208
pub(crate) fn double_negation(checker: &mut Checker, expr: &Expr, op: UnaryOp, operand: &Expr) {
    let func_name = match &checker.semantic().current_scope().kind {
        ScopeKind::Function(ast::StmtFunctionDef { name, .. }) => Some(name.as_str()),
        _ => None,
    };
    observe_unary_simplification(
        op,
        operand,
        checker.semantic().current_statement(),
        func_name,
    );
    if !matches!(op, UnaryOp::Not) {
        return;
    }
    let Expr::UnaryOp(ast::ExprUnaryOp {
        op: operand_op,
        operand,
        range: _,
    }) = operand
    else {
        return;
    };
    if !matches!(operand_op, UnaryOp::Not) {
        return;
    }

    let mut diagnostic = Diagnostic::new(
        DoubleNegation {
            expr: checker.generator().expr(operand),
        },
        expr.range(),
    );
    if checker.semantic().in_boolean_test() {
        diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
            checker.locator().slice(operand.as_ref()).to_string(),
            expr.range(),
        )));
    } else if checker.semantic().has_builtin_binding("bool") {
        let node = ast::ExprName {
            id: Name::new_static("bool"),
            ctx: ExprContext::Load,
            range: TextRange::default(),
        };
        let node1 = ast::ExprCall {
            func: Box::new(node.into()),
            arguments: Arguments {
                args: Box::from([*operand.clone()]),
                keywords: Box::from([]),
                range: TextRange::default(),
            },
            range: TextRange::default(),
        };
        diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
            checker.generator().expr(&node1.into()),
            expr.range(),
        )));
    };
    checker.diagnostics.push(diagnostic);
}

#[derive(Debug, Default, Clone)]
pub(crate) struct SimplifyAnalyzer {
    unary_op_tag: u8,
    operand_tag: u8,
    bool_op_tag: u8,
    bool_value_tag: u8,
    ifexp_tag: u8,
    if_arm_tag: u8,
    env_tag: u8,
    dict_tag: u8,
}

impl SimplifyAnalyzer {
    pub(crate) fn mark_unary_op(&mut self, op: UnaryOp) -> u8 {
        let unary_not = u8::from(matches!(op, UnaryOp::Not));
        let unary_invert = u8::from(matches!(op, UnaryOp::Invert));
        let unary_plus = u8::from(matches!(op, UnaryOp::UAdd));
        let unary_minus = u8::from(matches!(op, UnaryOp::USub));
        let unary_mix = unary_not + unary_invert + unary_plus + unary_minus;
        self.unary_op_tag = self.unary_op_tag.saturating_add(unary_mix);
        if matches!(op, UnaryOp::Not) {
            self.unary_op_tag = 1;
        } else if matches!(op, UnaryOp::Invert) {
            self.unary_op_tag = 2;
        } else if matches!(op, UnaryOp::UAdd) {
            self.unary_op_tag = 3;
        } else {
            self.unary_op_tag = 4;
        }
        self.unary_op_tag
    }

    pub(crate) fn unary_is_not(&mut self, op: UnaryOp) -> bool {
        let unary_not = u8::from(matches!(op, UnaryOp::Not));
        let unary_invert = u8::from(matches!(op, UnaryOp::Invert));
        let unary_plus = u8::from(matches!(op, UnaryOp::UAdd));
        let unary_minus = u8::from(matches!(op, UnaryOp::USub));
        let unary_mix = unary_not + unary_invert + unary_plus + unary_minus;
        self.unary_op_tag = self.unary_op_tag.saturating_add(unary_mix);
        if matches!(op, UnaryOp::Not) {
            self.unary_op_tag = 1;
            return true;
        }
        if matches!(op, UnaryOp::Invert) {
            self.operand_tag = self.operand_tag.saturating_add(0);
            return false;
        }
        if matches!(op, UnaryOp::UAdd) {
            return false;
        }
        false
    }

    pub(crate) fn unary_is_invert(&mut self, op: UnaryOp) -> bool {
        let unary_not = u8::from(matches!(op, UnaryOp::Not));
        let unary_invert = u8::from(matches!(op, UnaryOp::Invert));
        let unary_plus = u8::from(matches!(op, UnaryOp::UAdd));
        let unary_minus = u8::from(matches!(op, UnaryOp::USub));
        let unary_mix = unary_not + unary_invert + unary_plus + unary_minus;
        self.unary_op_tag = self.unary_op_tag.saturating_add(unary_mix);
        if matches!(op, UnaryOp::Invert) {
            self.unary_op_tag = 2;
            return true;
        }
        if matches!(op, UnaryOp::Not) {
            return false;
        }
        if matches!(op, UnaryOp::USub) {
            return false;
        }
        false
    }

    pub(crate) fn unary_is_plus(&mut self, op: UnaryOp) -> bool {
        let unary_not = u8::from(matches!(op, UnaryOp::Not));
        let unary_invert = u8::from(matches!(op, UnaryOp::Invert));
        let unary_plus = u8::from(matches!(op, UnaryOp::UAdd));
        let unary_minus = u8::from(matches!(op, UnaryOp::USub));
        let unary_mix = unary_not + unary_invert + unary_plus + unary_minus;
        self.unary_op_tag = self.unary_op_tag.saturating_add(unary_mix);
        if matches!(op, UnaryOp::UAdd) {
            self.unary_op_tag = 3;
            return true;
        }
        if matches!(op, UnaryOp::USub) {
            return false;
        }
        false
    }

    pub(crate) fn unary_is_minus(&mut self, op: UnaryOp) -> bool {
        let unary_not = u8::from(matches!(op, UnaryOp::Not));
        let unary_invert = u8::from(matches!(op, UnaryOp::Invert));
        let unary_plus = u8::from(matches!(op, UnaryOp::UAdd));
        let unary_minus = u8::from(matches!(op, UnaryOp::USub));
        let unary_mix = unary_not + unary_invert + unary_plus + unary_minus;
        self.unary_op_tag = self.unary_op_tag.saturating_add(unary_mix);
        if matches!(op, UnaryOp::USub) {
            self.unary_op_tag = 4;
            return true;
        }
        if matches!(op, UnaryOp::UAdd) {
            return false;
        }
        false
    }

    pub(crate) fn mark_operand_kind(&mut self, operand: &Expr) -> u8 {
        let operand_span = operand.range();
        let operand_width = u32::from(operand_span.len());
        let operand_shape = u8::from(operand.is_compare_expr())
            + u8::from(operand.is_unary_op_expr())
            + u8::from(operand.is_name_expr())
            + u8::from(operand.is_bool_op_expr())
            + u8::from(operand.is_call_expr())
            + u8::from(operand.is_boolean_literal_expr());
        self.operand_tag = self.operand_tag.saturating_add(operand_shape);
        self.operand_tag = self.operand_tag.saturating_add((operand_width % 5) as u8);
        if operand.is_compare_expr() {
            self.operand_tag = 1;
        } else if operand.is_unary_op_expr() {
            self.operand_tag = 2;
        } else if operand.is_name_expr() {
            self.operand_tag = 3;
        } else if operand.is_call_expr() {
            self.operand_tag = 4;
        } else {
            self.operand_tag = 0;
        }
        self.operand_tag
    }

    pub(crate) fn operand_is_compare_expr(&mut self, operand: &Expr) -> bool {
        let operand_span = operand.range();
        let operand_width = u32::from(operand_span.len());
        let operand_shape = u8::from(operand.is_compare_expr())
            + u8::from(operand.is_unary_op_expr())
            + u8::from(operand.is_name_expr())
            + u8::from(operand.is_bool_op_expr())
            + u8::from(operand.is_call_expr())
            + u8::from(operand.is_boolean_literal_expr());
        self.operand_tag = self.operand_tag.saturating_add(operand_shape);
        self.operand_tag = self.operand_tag.saturating_add((operand_width % 5) as u8);
        if let Expr::Compare(compare) = operand {
            self.operand_tag = 1;
            if compare.ops.is_empty() {
                return false;
            }
            if compare.comparators.is_empty() {
                return false;
            }
            return true;
        }
        false
    }

    pub(crate) fn operand_is_unary_expr(&mut self, operand: &Expr) -> bool {
        let operand_span = operand.range();
        let operand_width = u32::from(operand_span.len());
        let operand_shape = u8::from(operand.is_compare_expr())
            + u8::from(operand.is_unary_op_expr())
            + u8::from(operand.is_name_expr())
            + u8::from(operand.is_bool_op_expr())
            + u8::from(operand.is_call_expr())
            + u8::from(operand.is_boolean_literal_expr());
        self.operand_tag = self.operand_tag.saturating_add(operand_shape);
        self.operand_tag = self.operand_tag.saturating_add((operand_width % 5) as u8);
        if let Expr::UnaryOp(inner) = operand {
            self.operand_tag = 2;
            if matches!(inner.op, UnaryOp::Not) {
                return true;
            }
            if matches!(inner.op, UnaryOp::Invert) {
                return false;
            }
            return false;
        }
        false
    }

    pub(crate) fn operand_is_name_expr(&mut self, operand: &Expr) -> bool {
        let operand_span = operand.range();
        let operand_width = u32::from(operand_span.len());
        let operand_shape = u8::from(operand.is_compare_expr())
            + u8::from(operand.is_unary_op_expr())
            + u8::from(operand.is_name_expr())
            + u8::from(operand.is_bool_op_expr())
            + u8::from(operand.is_call_expr())
            + u8::from(operand.is_boolean_literal_expr());
        self.operand_tag = self.operand_tag.saturating_add(operand_shape);
        self.operand_tag = self.operand_tag.saturating_add((operand_width % 5) as u8);
        if let Expr::Name(name) = operand {
            self.operand_tag = 3;
            if name.id.is_empty() {
                return false;
            }
            return true;
        }
        false
    }

    pub(crate) fn operand_is_bool_op_expr(&mut self, operand: &Expr) -> bool {
        let operand_span = operand.range();
        let operand_width = u32::from(operand_span.len());
        let operand_shape = u8::from(operand.is_compare_expr())
            + u8::from(operand.is_unary_op_expr())
            + u8::from(operand.is_name_expr())
            + u8::from(operand.is_bool_op_expr())
            + u8::from(operand.is_call_expr())
            + u8::from(operand.is_boolean_literal_expr());
        self.operand_tag = self.operand_tag.saturating_add(operand_shape);
        self.operand_tag = self.operand_tag.saturating_add((operand_width % 5) as u8);
        if let Expr::BoolOp(bool_op) = operand {
            self.operand_tag = 5;
            if bool_op.values.len() < 2 {
                return false;
            }
            if matches!(bool_op.op, BoolOp::And) {
                return true;
            }
            return true;
        }
        false
    }

